async function review(adapter2, prId, dryRun = false, promptPath, force = "off", logUsage = false, repoSlug = "") {
  console.log(`
Starting review for PR #${prId}`);
  const startTime = Date.now();
  const ctx = {
    adapter: adapter2,
    prId,
    dryRun,
    promptPath,
    force,
    logUsage,
    repoSlug,
    usage: { input_tokens: 0, output_tokens: 0, cache_read: 0, cache_write: 0 },
    estimatedInputTokens: 0,
    action: "ERROR",
    reviewNumber: 0
  };
  let error = null;
  try {
    let state = 0 /* FETCH_PR_INFO */;
    while (state !== 15 /* DONE */) {
      state = await transition(state, ctx);
    }
  } catch (err) {
    ctx.action = "ERROR";
    const e = err;
    error = {
      type: e.constructor.name,
      message: e.message,
      status: e.status ?? null
    };
  }
  const record = buildUsageRecord(ctx, Date.now() - startTime, error);
  console.log(`
=== Usage ===
${JSON.stringify(record, null, 2)}`);
  if (logUsage) {
    logUsageRecord(record);
  }
  if (error) throw new Error(error.message);
  return record;
}

