var [major] = process.versions.node.split(".").map(Number);
if (major < 22) {
  console.error(`Node.js 22+ required. Current: ${process.version}`);
  process.exit(1);
}
var program2 = new Command();
program2.name("pr-review-agent").description("Automated PR code review powered by Claude").option("--pr-id <id>", "Pull request ID").option("--workspace <workspace>", "VCS workspace / org (overrides BITBUCKET_WORKSPACE)").option("--repo-slug <slug>", "Repository slug").option("--vcs <provider>", "VCS provider: bitbucket | azure (WIP) | github | gitlab (overrides VCS_PROVIDER)").option("--dry-run", "Print the review to stdout without posting to the PR").option("--force [mode]", 'Force review: "clean" (no prior context) or "re-review" (keep context, bypass dedup)').option("--log-usage [bool]", "Log usage data to results.jsonl (default: true)", (v) => v !== "false", true).option("--prompt <path>", "Path to a local prompt file (overrides repo .agent-review-instructions.md)").option("--validate-prompt", "Validate prompt and exit (local via --prompt, or repo via --pr-id)").option("--model <id>", "Claude model ID (overrides CLAUDE_MODEL)").option("--judge-model <id>", "Judge model ID (overrides JUDGING_MODEL)").option("--min-changed-files <n>", "Skip review if fewer files changed (overrides MIN_CHANGED_FILES)").option("--max-changed-files <n>", "Skip review if more files changed (overrides MAX_CHANGED_FILES)").option("--min-changed-lines <n>", "Skip review if fewer lines changed (overrides MIN_CHANGED_LINES)").option("--max-changed-lines <n>", "Skip review if more lines changed (overrides MAX_CHANGED_LINES)").parse(process.argv);
var opts = program2.opts();
async function main() {
  if (opts.validatePrompt) {
    if (opts.prompt) {
      validateLocalPrompt(opts.prompt);
      return;
    }
    if (!opts.prId) {
      console.error("Error: --validate-prompt requires --prompt <path> or --pr-id <id>");
      process.exit(1);
    }
  }
  if (!opts.prId) {
    console.error("Error: --pr-id is required");
    process.exit(1);
  }
  const provider = opts.vcs ?? config.vcsProvider;
  config.vcsProvider = provider;
  let adapter2;
  if (provider === "bitbucket") {
    if (opts.workspace) config.bitbucket.workspace = opts.workspace;
    validateBitbucketConfig();
    const bb = new BitbucketAdapter(
      config.bitbucket.baseUrl,
      config.bitbucket.workspace,
      config.bitbucket.username,
      config.bitbucket.token
    );
    if (!opts.repoSlug) {
      console.error("Error: --repo-slug is required for Bitbucket");
      process.exit(1);
    }
    bb.setRepoSlug(opts.repoSlug);
    adapter2 = bb;
  } else if (provider === "azure") {
    if (opts.workspace) config.azure.org = opts.workspace;
    validateAzureConfig();
    const az = new AzureDevOpsAdapter(
      config.azure.baseUrl,
      config.azure.org,
      config.azure.project,
      config.azure.pat,
      config.azure.accessToken
    );
    if (!opts.repoSlug) {
      console.error("Error: --repo-slug is required for Azure DevOps");
      process.exit(1);
    }
    az.setRepoSlug(opts.repoSlug);
    adapter2 = az;
  } else if (provider === "github") {
    adapter2 = new GitHubAdapter();
  } else if (provider === "gitlab") {
    adapter2 = new GitLabAdapter();
  } else {
    console.error(`Unknown VCS provider: ${provider}`);
    process.exit(1);
  }
  if (opts.validatePrompt) {
    const prInfo = await adapter2.getPullRequestInfo(opts.prId);
    const changedFiles = await adapter2.getChangedFiles(opts.prId);
    const result = await loadPrompt(adapter2, prInfo, void 0, changedFiles);
    console.log(`
Filled prompt length: ${result.content.length} chars (~${Math.ceil(result.content.length / 4).toLocaleString()} tokens)`);
    return;
  }
  if (opts.model) config.anthropic.model = opts.model;
  if (opts.judgeModel) config.judge.model = opts.judgeModel;
  if (opts.minChangedFiles) config.thresholds.minChangedFiles = parseInt(opts.minChangedFiles, 10);
  if (opts.maxChangedFiles) config.thresholds.maxChangedFiles = parseInt(opts.maxChangedFiles, 10);
  if (opts.minChangedLines) config.thresholds.minChangedLines = parseInt(opts.minChangedLines, 10);
  if (opts.maxChangedLines) config.thresholds.maxChangedLines = parseInt(opts.maxChangedLines, 10);
  const forceMode = opts.force === true ? "re-review" : typeof opts.force === "string" ? opts.force : "off";
  await review(adapter2, opts.prId, opts.dryRun ?? false, opts.prompt, forceMode, opts.logUsage ?? true, opts.repoSlug ?? "");
}
main().catch((err) => {
  console.error("Fatal error:", err.message);
  process.exit(1);
});
